arguments.old:
// fixed pins with retaining caps
for (i = [0 : 3]) {
    c = centres[i];
    top = (i == 0) ? cap1_bot + cap_h : cap_bot + cap_h;
    translate([c[0], c[1], 0]) cylinder(r = pin_r, h = top, $fn = 36);
    translate([c[0], c[1], (i == 0) ? cap1_bot : cap_bot])
        cylinder(r = cap_r, h = cap_h, $fn = 36);
}

arguments.new:
// fixed pins with retaining caps (caps 45 deg conical: no support needed)
for (i = [0 : 3]) {
    c = centres[i];
    bot = (i == 0) ? cap1_bot : cap_bot;
    translate([c[0], c[1], 0]) cylinder(r = pin_r, h = bot + cap_h, $fn = 36);
    translate([c[0], c[1], bot]) cylinder(r1 = cap_r, r2 = pin_r, h = cap_h, $fn = 36);
}
